-- Real Estate CRM: draft schema (Postgres / Supabase)
-- STATUS: untested draft. Run it first in a throwaway dev project with FAKE data only.
--
-- Conventions:
--   * id            uuid primary key, generated by Postgres
--   * owner_id      the logged-in user who owns the row (the "scaling door" + what security rules key on)
--   * created_at    when the row was created
--   * Text columns with CHECK constraints (instead of ENUM types) so adding a new
--     option later is a one-line change.

-- ---------------------------------------------------------------------------
-- clients: a person (buyer, seller, or both)
-- ---------------------------------------------------------------------------
create table clients (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  full_name   text not null,
  email       text,
  phone       text,
  kind        text not null default 'buyer'
              check (kind in ('buyer', 'seller', 'both')),
  notes       text,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- cases: one client + one property address (a client can have many over time)
-- ---------------------------------------------------------------------------
create table cases (
  id               uuid primary key default gen_random_uuid(),
  owner_id         uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- RESTRICT: Postgres refuses to delete a client who still has cases.
  client_id        uuid not null references clients (id) on delete restrict,
  property_address text not null,
  status           text not null default 'prospect'
                   check (status in ('prospect', 'listed', 'under_contract', 'closed', 'fell_through')),
  acceptance_date  date,
  created_at       timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- key_dates: one row per important date on a case
-- Adding a new date type later = adding one value to the CHECK list below.
-- ---------------------------------------------------------------------------
create table key_dates (
  id            uuid primary key default gen_random_uuid(),
  owner_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- CASCADE: deleting a case also deletes its dates.
  case_id       uuid not null references cases (id) on delete cascade,
  kind          text not null
                check (kind in (
                  'list_date',
                  'emd_deadline',
                  'inspection_deadline',
                  'financing_deadline',
                  'appraisal_deadline',
                  'walkthrough',
                  'closing',
                  'other'
                )),
  label         text,                 -- optional custom text, mainly for kind = 'other'
  due_date      date not null,
  completed_at  timestamptz,          -- null = still open; a timestamp = done (and when)
  notes         text,
  created_at    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- documents: metadata about a file stored in private file storage
-- (the file itself lives in a storage bucket; this row points to it)
-- ---------------------------------------------------------------------------
create table documents (
  id                uuid primary key default gen_random_uuid(),
  owner_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- RESTRICT: don't silently orphan stored files by deleting the case.
  case_id           uuid not null references cases (id) on delete restrict,
  storage_path      text not null,    -- path inside the private storage bucket
  file_name         text not null,
  doc_type          text not null default 'other'
                    check (doc_type in ('purchase_agreement', 'inspection_report', 'disclosure', 'other')),
  summary           text,
  summary_source    text check (summary_source in ('manual', 'ai')),
  summary_reviewed  boolean not null default false,  -- AI summaries stay a draft until she confirms
  uploaded_at       timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- notes: free-text entries; show up on the client timeline
-- ---------------------------------------------------------------------------
create table notes (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  client_id   uuid not null references clients (id) on delete cascade,
  case_id     uuid references cases (id) on delete cascade,   -- optional: note about a specific case
  body        text not null,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Indexes: speed up the two main screens
-- ---------------------------------------------------------------------------
create index key_dates_owner_due_idx on key_dates (owner_id, due_date) where completed_at is null;
create index key_dates_case_idx      on key_dates (case_id);
create index cases_client_idx        on cases (client_id);
create index documents_case_idx      on documents (case_id);
create index notes_client_idx        on notes (client_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Row-level security: a logged-in user can only touch rows where owner_id is theirs.
-- With RLS enabled and no matching policy, access is denied by default.
-- ---------------------------------------------------------------------------
alter table clients   enable row level security;
alter table cases     enable row level security;
alter table key_dates enable row level security;
alter table documents enable row level security;
alter table notes     enable row level security;

create policy "owner full access" on clients
  for all to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

create policy "owner full access" on cases
  for all to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

create policy "owner full access" on key_dates
  for all to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

create policy "owner full access" on documents
  for all to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

create policy "owner full access" on notes
  for all to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Grants: this project is created with "Automatically expose new tables" OFF, so each
-- table needs an explicit grant before the app (logged-in users only) can reach it.
-- Deliberately NO grants to anon: logged-out visitors get nothing.
-- RLS policies above still decide which rows each logged-in user may touch.
-- ---------------------------------------------------------------------------
grant select, insert, update, delete on public.clients   to authenticated;
grant select, insert, update, delete on public.cases     to authenticated;
grant select, insert, update, delete on public.key_dates to authenticated;
grant select, insert, update, delete on public.documents to authenticated;
grant select, insert, update, delete on public.notes     to authenticated;

-- TODO (separate step): create a PRIVATE storage bucket for documents and add storage
--       policies so files are only readable by their owner (via short-lived signed links).

